import { drizzle } from "drizzle-orm/node-postgres";
import { Client } from "pg";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { schema } from "@/lib/db/schema";

const databaseUrl = process.env.DATABASE_URL;

if (databaseUrl) {
  describe("sighting persistence", () => {
    let client: Client;

    beforeEach(async () => {
      client = new Client({ connectionString: databaseUrl });
      await client.connect();
      await client.query('DROP TABLE IF EXISTS "sightings"');

      const migration = await readFile(
        new URL(
          "../../drizzle/20260811072733_early_luke_cage/migration.sql",
          import.meta.url
        ),
        "utf8"
      );
      for (const statement of migration.split("--> statement-breakpoint")) {
        await client.query(statement);
      }
    });

    afterEach(async () => {
      await client.end();
    });

    it("applies the baseline constraints and permits duplicate label facts", async () => {
      const database = drizzle(databaseUrl, { schema });
      const { createSightingOperations } = await import("./sightings.server");
      const operations = createSightingOperations(database);

      try {
        const first = await operations.create({
          labelDate: "2026-08-11",
          labelMinute: 845,
        });
        const duplicate = await operations.create({
          labelDate: "2026-08-11",
          labelMinute: 845,
        });

        expect(first).toMatchObject({
          ok: true,
          sighting: {
            doneness: null,
            labelDate: "2026-08-11",
            labelMinute: 845,
          },
        });
        expect(duplicate).toMatchObject({
          ok: true,
          sighting: { labelDate: "2026-08-11", labelMinute: 845 },
        });
        expect(
          first.ok && duplicate.ok && duplicate.sighting.id
        ).toBeGreaterThan(first.ok ? first.sighting.id : 0);

        await expect(
          client.query(
            "insert into sightings (label_date, label_minute) values ('2026-08-11', 1440)"
          )
        ).rejects.toMatchObject({ code: "23514" });
        await expect(
          client.query(
            "insert into sightings (label_date, label_minute, doneness) values ('2026-08-11', 0, 'raw')"
          )
        ).rejects.toMatchObject({ code: "23514" });
      } finally {
        await database.$client.end();
      }
    });

    it("creates the required representation and only its initial recency index", async () => {
      const columns = await client.query<{ column_name: string }>(
        "select column_name from information_schema.columns where table_name = 'sightings' order by ordinal_position"
      );
      const indexes = await client.query<{ indexname: string }>(
        "select indexname from pg_indexes where tablename = 'sightings' order by indexname"
      );

      expect(columns.rows.map((column) => column.column_name)).toEqual([
        "id",
        "label_date",
        "label_minute",
        "doneness",
        "created_at",
        "updated_at",
      ]);
      expect(indexes.rows.map((index) => index.indexname)).toEqual([
        "sightings_pkey",
        "sightings_recent_idx",
      ]);
    });
  });
}
import { desc, sql } from "drizzle-orm";
import {
  check,
  date,
  index,
  integer,
  pgTable,
  smallint,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

import { DONENESS_VALUES } from "../sightings";

export const sightings = pgTable(
  "sightings",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    labelDate: date("label_date", { mode: "string" }).notNull(),
    labelMinute: smallint("label_minute").notNull(),
    doneness: text({ enum: DONENESS_VALUES }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    check(
      "sightings_label_minute_check",
      sql`${table.labelMinute} between 0 and 1439`
    ),
    check(
      "sightings_doneness_check",
      sql`${table.doneness} in ('light', 'medium', 'dark')`
    ),
    index("sightings_recent_idx").on(desc(table.createdAt), desc(table.id)),
  ]
);

export const schema = { sightings };

export type Sighting = typeof sightings.$inferSelect;
import { createServerFn } from "@tanstack/react-start";

import { createSightingInputSchema } from "@/lib/sightings";

export const saveSighting = createServerFn({ method: "POST" })
  .inputValidator(createSightingInputSchema)
  .handler(async ({ data }) => {
    const { sightingOperations } = await import("@/lib/sightings.server");

    return sightingOperations.create(data);
  });
import type { NodePgDatabase } from "drizzle-orm/node-postgres";

import { db } from "@/lib/db";
import { type schema, sightings } from "@/lib/db/schema";
import {
  type CreateSighting,
  type CreateSightingInput,
  type CreateSightingResult,
  SAVE_FAILURE_MESSAGE,
} from "@/lib/sightings";

type Database = NodePgDatabase<typeof schema>;

export function createSightingOperations(database: Database): {
  create: CreateSighting;
} {
  return {
    create: async (
      input: CreateSightingInput
    ): Promise<CreateSightingResult> => {
      try {
        const [record] = await database
          .insert(sightings)
          .values(input)
          .returning();

        if (!record) {
          return { message: SAVE_FAILURE_MESSAGE, ok: false };
        }

        return { ok: true, sighting: record };
      } catch {
        return { message: SAVE_FAILURE_MESSAGE, ok: false };
      }
    },
  };
}

export const sightingOperations = createSightingOperations(db);
import { z } from "zod";

export const DONENESS_VALUES = ["light", "medium", "dark"] as const;
export type Doneness = (typeof DONENESS_VALUES)[number];

export const createSightingInputSchema = z.object({
  labelDate: z.iso.date(),
  labelMinute: z.int().min(0).max(1439),
});

export type CreateSightingInput = z.infer<typeof createSightingInputSchema>;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
export type Sighting = {
  createdAt: Date;
  doneness: Doneness | null;
  id: number;
  labelDate: string;
  labelMinute: number;
  updatedAt: Date;
};

export type CreateSightingResult =
  | { ok: true; sighting: Sighting }
  | { message: string; ok: false };

export type CreateSighting = (
  input: CreateSightingInput
) => Promise<CreateSightingResult>;

export const SAVE_FAILURE_MESSAGE =
  "Unable to save label time. Check your connection and try again.";

